import json
import collections

def get_passable_tiles(map_id):
    passable = set()
    if map_id == '0_232':  # B1F
        # 1. Starting Chamber
        for x in range(28, 38):
            for y in range(21, 30):
                passable.add((x, y))
        # 2. Southern Corridor
        for x in range(2, 38):
            for y in range(30, 34):
                passable.add((x, y))
        # 3. Western Connecting Passage
        for x in range(14, 21):
            for y in range(24, 30):
                if (x, y) != (14, 28):  # Blocked by trainer sprite
                    passable.add((x, y))
        # 4. Upper Bypass Corridor
        for x in range(20, 30):
            for y in [18, 19]:
                passable.add((x, y))
        # 5. Western vertical/horizontal bypass corridor
        for x in range(20, 26):
            for y in range(21, 26):
                passable.add((x, y))
        # 6. Rows 16-17 Corridor (Expanded to 37 inclusive, range(14, 38))
        for x in range(14, 38):
            for y in [16, 17]:
                passable.add((x, y))
        # 7. Northern B1F Corridor
        for x in range(29, 39):
            passable.add((x, 2))
        passable.add((27, 3))
        passable.add((28, 3))
        # 8. Middle-Right Corridor
        for x in range(26, 38):
            for y in range(10, 14):
                passable.add((x, y))
        # 9. Middle-Left Corridor
        for x in range(14, 24):
            for y in range(10, 14):
                passable.add((x, y))
        # 10. Column 17 Vertical Corridor
        for y in range(13, 22):
            passable.add((17, y))
        # 11. Columns 14-23 Rows 5-9 (Northern Corridor)
        for x in range(14, 24):
            for y in range(5, 10):
                passable.add((x, y))

    elif map_id == '0_82':  # 1F
        # Starting area
        for x in range(14, 18):
            for y in range(3, 8):
                passable.add((x, y))
        for x in range(18, 29):
            for y in range(4, 8):
                passable.add((x, y))
        # Middle Corridor
        for x in range(20, 34):
            for y in range(10, 14):
                passable.add((x, y))
        # Eastern Corridor
        for x in range(34, 38):
            for y in range(2, 14):
                passable.add((x, y))
        # Northern 1F
        for x in range(2, 11):
            for y in range(2, 17):
                passable.add((x, y))
        # Southern 1F
        for x in range(4, 20):
            for y in range(16, 22):
                if (x, y) != (5, 16):  # Blocked by Hiker
                    passable.add((x, y))

    return passable

def solve_bfs(map_id, start, target):
    passable = get_passable_tiles(map_id)
    if start not in passable:
        # Fallback to allow starting on unmapped tile
        passable.add(start)
    if target not in passable:
        passable.add(target)

    queue = collections.deque([[start]])
    seen = {start}

    while queue:
        path = queue.popleft()
        x, y = path[-1]
        if (x, y) == target:
            return path

        for dx, dy, btn in [(-1, 0, 'Left'), (1, 0, 'Right'), (0, -1, 'Up'), (0, 1, 'Down')]:
            nx, ny = x + dx, y + dy
            if (nx, ny) in passable and (nx, ny) not in seen:
                seen.add((nx, ny))
                queue.append(path + [(nx, ny)])
    return None

def path_to_buttons(path):
    buttons = []
    for i in range(len(path) - 1):
        x1, y1 = path[i]
        x2, y2 = path[i+1]
        if x2 > x1:
            buttons.append('Right')
        elif x2 < x1:
            buttons.append('Left')
        elif y2 > y1:
            buttons.append('Down')
        elif y2 < y1:
            buttons.append('Up')
    return buttons

# Main script logic
input_data = {}
try:
    # Under standard tool harness, input parameters are passed in a global variable or json
    # Let's read from the auto-loaded input dictionary
    input_data = json.loads(open('input_data.json').read())
except:
    pass

map_id = input_data.get('map_id', '0_232')
start_x = int(input_data.get('start_x', 37))
start_y = int(input_data.get('start_y', 16))
target_x = int(input_data.get('target_x', 23))
target_y = int(input_data.get('target_y', 11))

path = solve_bfs(map_id, (start_x, start_y), (target_x, target_y))
if path:
    buttons = path_to_buttons(path)
    print(json.dumps(buttons))
else:
    print(json.dumps([]))
